function social_icon(string $platform, int $size = 20): string
{
    $p = social_platforms()[$platform] ?? social_platforms()['website'];
    return '<svg width="' . $size . '" height="' . $size . '" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">' . $p[1] . '</svg>';
}

function social_name(string $platform): string
{
    return social_platforms()[$platform][0] ?? ucfirst($platform);
}

